public sealed record IndividualProfileView(Guid Id,string FirstName,string LastName,string? NationalId,string? FatherName,DateOnly? BirthDate,string? GenderCode,string? BirthCertificateNumber,string? PlaceOfIssue,string? Occupation,long Version);
public sealed record LegalProfileView(Guid Id,string LegalName,string? TradeName,string? NationalId,string? RegistrationNumber,DateOnly? EstablishmentDate,string? LegalEntityTypeCode,string? BusinessActivity,string? Website,string? ManagingDirector,long Version) { public Guid? LegalEntityTypeId { get; init; } }
public sealed record CustomerView(Guid Id,Guid CompanyId,string CustomerCode,CustomerType CustomerType,string DisplayName,CustomerStatus Status,string? PrimaryMobile,string? PrimaryPhone,string? PrimaryEmail,string? EconomicCode,string? CustomerGroupCode,string? PriceGroupCode,Guid? SalesRepresentativePersonId,string? SalesRepresentativeName,string? Notes,DateTimeOffset CreatedAtUtc,DateTimeOffset UpdatedAtUtc,long Version,IndividualProfileView? IndividualProfile,LegalProfileView? LegalProfile)
{ public Guid? CustomerGroupId { get; init; } public Guid? PriceGroupId { get; init; }  public bool IsActive=>Status==CustomerStatus.Active; public string? FirstName=>IndividualProfile?.FirstName; public string? LastName=>IndividualProfile?.LastName; public string? LegalName=>LegalProfile?.LegalName; public string? NationalId=>IndividualProfile?.NationalId??LegalProfile?.NationalId; public string? RegistrationNo=>LegalProfile?.RegistrationNumber; public string? TaxId=>EconomicCode; }
public sealed record CustomerDirectoryView(Guid Id,string CustomerCode,string DisplayName,CustomerType CustomerType,string? PrimaryMobile,string? CustomerGroupCode,string? SalesRepresentativeName,CustomerStatus Status,long Version);
public sealed record CustomerOptionView(Guid Id,string CustomerCode,string DisplayName,CustomerType CustomerType,string? PrimaryMobile);
public sealed record SalesRepresentativeOption(Guid PersonId,string DisplayName,string? PersonnelCode,string? Mobile);
public sealed record CustomerContactView(Guid Id,Guid CustomerId,string ContactTypeCode,string FirstName,string? LastName,string? Mobile,string? Phone,string? Email,string? PositionTitle,string? Notes,bool IsPrimary,bool IsActive,int DisplayOrder,long Version)
{ public Guid? ContactRoleId { get; init; }  public string Name=>string.Join(' ',new[]{FirstName,LastName}.Where(x=>!string.IsNullOrWhiteSpace(x))); public string? JobTitle=>PositionTitle; }
public sealed record CustomerAddressView(Guid Id,Guid CustomerId,string AddressTypeCode,string Title,string CountryCode,string? ProvinceCode,string? CityCode,string? District,string AddressLine1,string? AddressLine2,string? PostalCode,string? RecipientName,string? RecipientPhone,string? RecipientMobile,bool IsDefault,bool IsActive,int DisplayOrder,long Version)
{ public Guid? AddressTypeId { get; init; } public string? Email { get; init; } public string? Notes { get; init; }  public bool IsPrimary=>IsDefault; public string? Province=>ProvinceCode; public string? City=>CityCode; }
public sealed record CustomerFinancialView(Guid Id,Guid CustomerId,decimal CreditLimit,decimal UsedCredit,decimal AvailableCredit,string? PaymentTermCode,string? PaymentConditionCode,string? PreferredPaymentMethodCode,decimal DefaultDiscountPercent,string? PriceGroupCode,string? CustomerGroupCode,Guid? SalesRepresentativePersonId,CustomerFinancialStatus FinancialStatus,decimal AccountBalance,string CalculationState,string? TaxStatusCode,string DefaultCurrencyCode,long Version) { public Guid? PaymentTermId { get; init; } public Guid? PaymentConditionId { get; init; } public Guid? PreferredPaymentMethodId { get; init; } public Guid? TaxStatusId { get; init; } }
public sealed record CustomerBankAccountView(Guid Id,Guid CustomerId,string? BankCode,string? BankName,string? AccountNumber,string? Iban,string AccountHolderName,string CurrencyCode,bool IsDefault,bool IsActive,string? Notes,long Version) { public Guid? BankId { get; init; } public Guid? AccountTypeId { get; init; } public string? AccountTypeCode { get; init; } public string? AccountName { get; init; } public BankAccountOwnership OwnershipType { get; init; } public string? CardNumber { get; init; } public string? BranchCode { get; init; } }
public sealed record CustomerDetailsView(CustomerView Customer,IReadOnlyList<CustomerAddressView> Addresses,IReadOnlyList<CustomerContactView> Contacts,CustomerFinancialView? FinancialProfile,IReadOnlyList<CustomerBankAccountView> BankAccounts);

