public sealed record AddressCommand(string AddressTypeCode,string Title,string CountryCode,string? ProvinceCode,string? CityCode,string? District,string AddressLine1,string? AddressLine2,string? PostalCode,string? RecipientName,string? RecipientPhone,string? RecipientMobile,bool IsDefault,int DisplayOrder,long Version=0,Guid? AddressTypeId=null,string? Email=null,string? Notes=null);
